-- Aquagram — 0054: Tür görselleri 10. parti (301–361 arası 59 tür + 1 form, 72 görsel; 303 eksik)
-- 314_!.webp → 314_1 (dawkinsia-filamentosa) olarak alındı. 327 = Tanichthys albonubes "Gold" formu.
update public.species s set images = (select array_agg('https://aquagram.com.tr/media/tur/' || v.slug || '-' || i || '.webp' order by i) from generate_series(1, v.adet) i)
from (values ('rasbora-daniconius',2),('rasbora-einthovenii',1),('trigonostigma-espei',2),('trigonostigma-hengeli',1),('trigonostigma-heteromorpha',1),('balantiocheilos-melanopterus',1),('barbodes-everetti',1),('barbodes-lateristriga',1),('barbodes-semifasciolatus',2),('barbonymus-schwanenfeldii',2),('crossocheilus-oblongus',1),('dawkinsia-arulius',2),('dawkinsia-filamentosa',1),('desmopuntius-hexazona',1),('desmopuntius-pentazona',1),('epalzeorhynchos-bicolor',1),('epalzeorhynchos-frenatum',2),('epalzeorhynchos-kalopterum',1),('haludaria-fasciata',1),('pethia-conchonius',2),('pethia-padamya',1),('puntigrus-tetrazona',1),('puntius-titteya',1),('sahyadria-denisonii',1),('tanichthys-albonubes',1),('acantopsis-dialuzona',1),('ambastaia-sidthimunki',1),('botia-almorhae',1),('botia-kubotai',1),('botia-striata',1),('chromobotia-macracanthus',1),('gastromyzon-punctulatus',1),('misgurnus-anguillicaudatus',2),('pangio-kuhlii',2),('pangio-oblonga',2),('pangio-semicincta',1),('petruichthys-sp-rosy',1),('pseudogastromyzon-myersi',1),('sewellia-elongata',1),('sewellia-lineolata',1),('syncrossus-berdmorei',1),('syncrossus-hymenophysa',1),('yaoshania-pachychilus',1),('yasuhikotakia-modesta',1),('yasuhikotakia-morleti',1),('agamyxis-pectinifrons',1),('ancistrus-sp',1),('baryancistrus-xanthellus',1),('bunocephalus-coracoideus',3),('corydoras-adolfoi',1),('corydoras-aeneus',1),('corydoras-duplicareus',1),('corydoras-habrosus',1),('corydoras-hastatus',1),('corydoras-julii',1),('corydoras-paleatus',1),('corydoras-panda',1),('corydoras-pygmaeus',1),('corydoras-sterbai',1)) as v(slug, adet)
where s.slug = v.slug;
update public.species_forms set images = array['https://aquagram.com.tr/media/tur/tanichthys-albonubes-gold-1.webp']::text[] where name = 'Gold' and species_id = (select id from public.species where slug = 'tanichthys-albonubes');
